from __future__ import annotations

from pathlib import Path

runner = Path("scripts/run_exa_exact_lot_checkpoint.py")
text = runner.read_text(encoding="utf-8")

start = text.index("def _exact_lot_rows(\n")
end = text.index("\n\ndef _candidate_from_exact_lot", start)

replacement = '''def _exact_lot_rows(\n    verification: Mapping[str, Any], multihop: Mapping[str, Any]\n) -> list[dict[str, Any]]:\n    accepted: list[dict[str, Any]] = []\n    accepted_by_identity: dict[str, int] = {}\n\n    def accept_preferred(row: dict[str, Any], identity_key: str) -> None:\n        existing_index = accepted_by_identity.get(identity_key)\n        if existing_index is None:\n            accepted_by_identity[identity_key] = len(accepted)\n            accepted.append(row)\n            return\n\n        existing = accepted[existing_index]\n        if _is_recovery_exact_lot(existing) and not _is_recovery_exact_lot(row):\n            accepted[existing_index] = row\n\n    for raw in verification.get("verified_pages") or []:\n        if not isinstance(raw, Mapping):\n            continue\n        classification = raw.get("classification")\n        rescued = _direct_row_is_rescuable_strict_exact(raw)\n        if classification != EXACT_LOT_CANDIDATE and not rescued:\n            continue\n        if not _strict_exact_evidence(row=raw, require_subject_evidence=False):\n            continue\n        row = dict(raw)\n        url = _compact(row.get("final_url") or row.get("url"))\n        identity_key = _exact_lot_identity_key(url)\n        if not url or not identity_key:\n            continue\n        row["url"] = url\n        row["final_url"] = url\n        row["exact_lot_origin"] = "DIRECT_SEARCH_RESULT"\n        if rescued:\n            row["direct_strict_evidence_rescue"] = DIRECT_STRICT_EVIDENCE_RESCUE\n        accept_preferred(row, identity_key)\n\n    for raw in multihop.get("exact_lots") or []:\n        if not isinstance(raw, Mapping):\n            continue\n        if not _strict_exact_evidence(row=raw, require_subject_evidence=True):\n            continue\n        row = dict(raw)\n        url = _compact(row.get("final_url") or row.get("url"))\n        identity_key = _exact_lot_identity_key(url)\n        if not url or not identity_key:\n            continue\n        row["url"] = url\n        row["final_url"] = url\n        row["exact_lot_origin"] = "MULTI_HOP"\n        accept_preferred(row, identity_key)\n\n    return accepted\n'''

old = text[start:end]
if "accepted_by_identity" in old:
    raise SystemExit("fresh provenance preference already applied")
if "seen: set[str] = set()" not in old:
    raise SystemExit("unexpected Exact-Lot row function shape")
text = text[:start] + replacement + text[end:]
runner.write_text(text, encoding="utf-8")


test = Path("tests/test_fresh_exact_lot_provenance_preference_v1.py")
test.write_text('''from __future__ import annotations\n\nimport importlib.util\nfrom pathlib import Path\n\nfrom opportunity_engine.discovery.exa_shadow_page_verification import EXACT_LOT_CANDIDATE\nfrom opportunity_engine.project_domain_boundary import CLOTHING_INVENTORY\n\n\ndef _load_runner():\n    path = Path("scripts/run_exa_exact_lot_checkpoint.py")\n    spec = importlib.util.spec_from_file_location("run_exa_exact_lot_checkpoint_fresh_preference_test", path)\n    assert spec is not None and spec.loader is not None\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module\n\n\ndef _strict_row(url: str, *, query: str = "") -> dict[str, object]:\n    return {\n        "classification": EXACT_LOT_CANDIDATE,\n        "title": "Kläder restparti",\n        "url": url,\n        "final_url": url,\n        "query": query,\n        "provider": "exa",\n        "evidence": {\n            "project_domain": CLOTHING_INVENTORY,\n            "page_subject_domain": CLOTHING_INVENTORY,\n            "item_specific_url_evidence": True,\n            "inventory_evidence": True,\n            "direct_sale_evidence": True,\n            "price_evidence": True,\n            "quantity_evidence": True,\n        },\n    }\n\n\ndef _recovery_row(url: str) -> dict[str, object]:\n    row = _strict_row(url)\n    row["provider"] = "proven_route_recovery"\n    row["retrieval_provenance"] = "PROVEN_ROUTE_RECOVERY"\n    return row\n\n\ndef _multihop_row(url: str, *, query: str) -> dict[str, object]:\n    row = _strict_row(url, query=query)\n    row.pop("classification", None)\n    return row\n\n\ndef test_fresh_current_exact_lot_replaces_cosmetic_recovery_duplicate() -> None:\n    runner = _load_runner()\n    query = "Sverige restparti kläder grossist lager"\n    verification = {\n        "verified_pages": [\n            _strict_row(\n                "https://cdon.se/produkt/parti-grossist-restparti-klader",\n                query=query,\n            ),\n            _recovery_row("https://grossist.se/restpartier/1/20/parti/2359"),\n            _recovery_row("https://www.grossist.se/restpartier/1/20/parti/2359/"),\n        ]\n    }\n    multihop = {\n        "exact_lots": [\n            _multihop_row(\n                "https://www.grossist.se/restpartier/1/20/parti/2359",\n                query=query,\n            )\n        ]\n    }\n\n    rows = runner._exact_lot_rows(verification, multihop)\n\n    assert len(rows) == 2\n    grossist = next(row for row in rows if "grossist.se" in str(row.get("url")))\n    assert grossist["provider"] == "exa"\n    assert grossist["query"] == query\n    assert grossist["exact_lot_origin"] == "MULTI_HOP"\n    assert runner._is_recovery_exact_lot(grossist) is False\n\n    snapshot = runner._fresh_coverage_snapshot(rows)\n    assert snapshot["total_strict_exact_lot_count"] == 2\n    assert snapshot["fresh_current_strict_exact_lot_count"] == 2\n    assert snapshot["reverified_recovery_strict_exact_lot_count"] == 0\n    assert snapshot["fresh_current_route_host_count"] == 2\n    assert snapshot["fresh_current_route_hosts"] == ["cdon.se", "grossist.se"]\n\n\ndef test_recovery_never_replaces_existing_fresh_identity() -> None:\n    runner = _load_runner()\n    query = "Sverige restparti kläder grossist lager"\n    fresh = _strict_row(\n        "https://www.grossist.se/restpartier/1/20/parti/2359/",\n        query=query,\n    )\n    recovery = _recovery_row("https://grossist.se/restpartier/1/20/parti/2359")\n\n    rows = runner._exact_lot_rows(\n        {"verified_pages": [fresh, recovery]},\n        {"exact_lots": []},\n    )\n\n    assert len(rows) == 1\n    assert rows[0]["provider"] == "exa"\n    assert rows[0]["query"] == query\n    assert runner._is_recovery_exact_lot(rows[0]) is False\n''', encoding="utf-8")
